import HealthKit

class HealthKitManager: ObservableObject {
    private let healthStore = HKHealthStore()
    @Published var steps: Double = 0

    init() {
        requestAuthorization()
    }

    / Berechtigungen anfragen
    func requestAuthorization() {
        guard HKHealthStore.isHealthDataAvailable() else {
            print("❌ HealthKit nicht verfügbar")
            return
        }

        guard let stepType = HKQuantityType.quantityType(forIdentifier: .stepCount) else { return }

        healthStore.requestAuthorization(toShare: [], read: [stepType]) { success, error in
            if success {
                print("✅ HealthKit Zugriff gewährt")
                self.fetchSteps()
            } else if let error = error {
                print("❌ Zugriff verweigert: \(error.localizedDescription)")
            }
        }
    }

    / Schrittanzahl abrufen
    func fetchSteps() {
        guard let stepType = HKQuantityType.quantityType(forIdentifier: .stepCount) else { return }

        let startOfDay = Calendar.current.startOfDay(for: Date())
        let predicate = HKQuery.predicateForSamples(withStart: startOfDay, end: Date(), options: .strictStartDate)

        let query = HKStatisticsQuery(quantityType: stepType, quantitySamplePredicate: predicate, options: .cumulativeSum) { _, result, _ in
            guard let result = result, let sum = result.sumQuantity() else { return }
            DispatchQueue.main.async {
                self.steps = sum.doubleValue(for: HKUnit.count())
                print("🚶 Schritte heute: \(Int(self.steps))")
            }
        }

        healthStore.execute(query)
    }
}

