    @Published var calories = 0.0

    init() { requestAccess() }

    func requestAccess() {
        guard let energyType = HKQuantityType.quantityType(forIdentifier: .activeEnergyBurned) else { return }
        store.requestAuthorization(toShare: [], read: [energyType]) { success, _ in
            if success { self.loadEnergy() }
        }
