class SleepManager: ObservableObject {
    private let store = HKHealthStore()
    @Published var sleepHours: Double = 0

    func requestAccess() {
        guard let sleepType = HKCategoryType.categoryType(forIdentifier: .sleepAnalysis) else { return }
        store.requestAuthorization(toShare: [], read: [sleepType]) { success, _ in
            if success { self.loadSleep() }
        }
    }

    func loadSleep() {
        guard let type = HKCategoryType.categoryType(forIdentifier: .sleepAnalysis) else { return }
        let start = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let predicate = HKQuery.predicateForSamples(withStart: start, end: Date())

        let query = HKSampleQuery(sampleType: type, predicate: predicate, limit: 20, sortDescriptors: nil) { _, samples, _ in
            let total = samples?.compactMap { sample -> Double? in
                guard let s = sample as? HKCategorySample else { return nil }
                return s.endDate.timeIntervalSince(s.startDate) / 3600
            }.reduce(0, +)

            DispatchQueue.main.async { self.sleepHours = total ?? 0 }
        }
        store.execute(query)
    }
}

