class BloodPressureManager: ObservableObject {
    private let store = HKHealthStore()
    @Published var systolic = 0.0
    @Published var diastolic = 0.0

    func requestAccess() {
        guard let sys = HKQuantityType.quantityType(forIdentifier: .bloodPressureSystolic),
              let dia = HKQuantityType.quantityType(forIdentifier: .bloodPressureDiastolic) else { return }

        store.requestAuthorization(toShare: [], read: [sys, dia]) { success, _ in
            if success { self.fetchBP() }
        }
    }

    func fetchBP() {
        guard let type = HKObjectType.correlationType(forIdentifier: .bloodPressure) else { return }
        let sort = NSSortDescriptor(key: HKSampleSortIdentifierEndDate, ascending: false)

        let query = HKSampleQuery(sampleType: type, predicate: nil, limit: 1, sortDescriptors: [sort]) { _, samples, _ in
            if let correlation = samples?.first as? HKCorrelation {
                if let sys = correlation.objects(for: HKObjectType.quantityType(forIdentifier: .bloodPressureSystolic)!).first as? HKQuantitySample {
                    self.systolic = sys.quantity.doubleValue(for: .millimeterOfMercury())
                }
                if let dia = correlation.objects(for: HKObjectType.quantityType(forIdentifier: .bloodPressureDiastolic)!).first as? HKQuantitySample {
                    self.diastolic = dia.quantity.doubleValue(for: .millimeterOfMercury())
                }
            }
        }
        store.execute(query)
    }
}

