class WaterManager: ObservableObject {
    private let store = HKHealthStore()

    func requestAccess() {
        guard let water = HKQuantityType.quantityType(forIdentifier: .dietaryWater) else { return }
        store.requestAuthorization(toShare: [water], read: [water]) { _, _ in }
    }

    func addWater(_ ml: Double) {
        guard let type = HKQuantityType.quantityType(forIdentifier: .dietaryWater) else { return }
        let quantity = HKQuantity(unit: .literUnit(with: .milli), doubleValue: ml)
        let sample = HKQuantitySample(type: type, quantity: quantity, start: .now, end: .now)
        store.save(sample) { _,_ in }
    }
}

